const P = ctx.params;
const R = P.rounds;
const wires = new PIXI.Graphics();
ctx.stage.addChild(wires);
const root = ctx.chip('$app', { color: ctx.colors.g2, textColor: 0x04101a, size: 12 });
root.x = ctx.width / 2; root.y = 32;
ctx.stage.addChild(root);
const nodes = [];
const step = ctx.width / (P.nodes.length + 1);
P.nodes.forEach((n, i) => {
  const c = ctx.chip(n, { color: ctx.colors.dim, textColor: 0xeaeeff, size: 11, minWidth: 84 });
  c.x = step * (i + 1); c.y = 88;
  wires.moveTo(root.x, root.y + 16).lineTo(c.x, c.y - 17).stroke({ width: 1.5, color: ctx.colors.g3, alpha: 0.35 });
  ctx.stage.addChild(c);
  nodes.push(c);
});
const all = nodes.map((n, i) => i);
const need = new PIXI.Text({ text: '', style: { fontFamily: 'JetBrains Mono, monospace', fontSize: 12, fill: ctx.colors.ink, align: 'center', wordWrap: true, wordWrapWidth: ctx.width - 56 } });
need.anchor.set(0.5); need.x = ctx.width / 2; need.y = 136;
ctx.stage.addChild(need);
const bar = new PIXI.Graphics();
ctx.stage.addChild(bar);
let idx = 0, score = 0, wrong = 0, left = 1, locked = true, chips = [];
function blast(list, color) {
  list.forEach((i) => {
    const n = nodes[i];
    const gl = ctx.glow(46, color, 1);
    gl.x = n.x; gl.y = n.y;
    ctx.stage.addChildAt(gl, 0);
    gsap.to(gl, { alpha: 0, duration: 0.9, onComplete: () => gl.destroy() });
    gsap.to(n.scale, { x: 1.18, y: 1.18, duration: 0.12, onComplete: () => gsap.to(n.scale, { x: 1, y: 1, duration: 0.3, ease: 'back.out' }) });
  });
}
function next() {
  chips.forEach((c) => c.destroy());
  chips = [];
  if (idx >= R.length) { bar.clear(); ctx.api.win('Smallest correct radius, every round.'); return; }
  const r = R[idx];
  need.text = 'NEEDED: ' + r.need;
  ctx.api.setGoal((idx + 1) + ' / ' + R.length);
  left = 1; locked = false;
  r.options.forEach((o, i) => {
    const c = ctx.chip(o.label, { color: ctx.colors.g3, textColor: 0x04101a, size: 11, minWidth: ctx.width - 88 });
    c.x = ctx.width / 2; c.y = 186 + i * 42;
    c.eventMode = 'static'; c.cursor = 'pointer';
    c.hitArea = new PIXI.Rectangle(-c.chipWidth / 2, -c.chipHeight / 2, c.chipWidth, c.chipHeight);
    c.on('pointertap', () => choose(i));
    ctx.stage.addChild(c);
    chips.push(c);
  });
}
function miss(msg) {
  wrong += 1;
  need.text = msg;
  if (wrong >= 3) { ctx.api.fail('Three loose writes. Radius is the whole game.'); return; }
  gsap.delayedCall(1.5, () => { idx += 1; next(); });
}
function choose(i) {
  if (locked) return;
  locked = true;
  const o = R[idx].options[i];
  const good = i === R[idx].best;
  blast(o.hits, good ? ctx.colors.good : ctx.colors.bad);
  if (good) {
    score += 1;
    ctx.api.setScore(score);
    need.text = o.why;
    gsap.delayedCall(1.5, () => { idx += 1; next(); });
  } else {
    miss(o.why);
  }
}
ctx.onTick((dt) => {
  if (locked) return;
  left -= dt / 660;
  bar.clear();
  if (left > 0) bar.roundRect(44, 312, (ctx.width - 88) * left, 5, 3).fill({ color: left > 0.3 ? ctx.colors.g1 : ctx.colors.warn });
  if (left <= 0) { locked = true; blast(all, ctx.colors.bad); miss('Too slow - the widest write fired itself.'); }
});
next();

